    for rel in contact.get('relationships', []):
        all_relationships.add(rel)
print("All relationship types in phone contacts:", all_relationships)

# Add phone friends not currently in venmo friends.
phone_friend_emails = {c['email'] for c in phone_friends}
venmo_friend_emails = {f['email'] for f in all_venmo_friends}

to_add = phone_friend_emails - venmo_friend_emails
to_remove = venmo_friend_emails - phone_friend_emails

