steps.code:
# Get details for all songs to match against old_songs
songs_info = {}
for song_id in all_song_ids:
    song = apis.spotify.show_song(song_id=song_id)
    if song:
        songs_info[song_id] = song

# Print all songs with their artists
for sid, song in songs_info.items():
    artists = [a['name'] for a in song['artists']]
    print(f"ID: {sid}, Title: {song['title']}, Artists: {artists}")

# Get details for all unique songs to match against old_songs.txt
song_details = {}
for song_id in sorted(all_song_ids):
    result = apis.spotify.show_song(song_id=song_id, access_token=spotify_token)
    song_details[song_id] = result
    print(f"Song {song_id}: {result['title']} by {', '.join(a['name'] for a in result['artists'])}")

