        line = line[2:]
    if ' by ' in line:
        title, artist = line.rsplit(' by ', 1)
        archived_songs.append({'title': title.strip(), 'artist': artist.strip()})
    else:
        # Maybe just title? But we'll assume format
        archived_songs.append({'title': line, 'artist': ''})

