# Search for each archived song to get its song_id
archived_song_ids = set()
song_id_to_info = {}

for title, artist in songs_to_archive:
    # Search with title and artist to narrow down
    query = f"{title} {artist}".strip()
    # Use page_limit=20 to get all results in one page
    results = apis.spotify.search_songs(query=query, access_token=spotify_token, page_limit=20)
    if results:
        # Find the best match: exact title and artist match
        found = False
        for song in results:
            song_title = song.get('title', '')
            song_artists = [a['name'] for a in song.get('artists', [])]
            # Check if title matches (case-insensitive) and artist matches
            if song_title.lower() == title.lower() and any(a.lower() == artist.lower() for a in song_artists):
                archived_song_ids.add(song['song_id'])
                song_id_to_info[song['song_id']] = (song_title, artist)
                found = True
                break
        if not found:
            # If not found, try just title
            results2 = apis.spotify.search_songs(query=title, access_token=spotify_token, page_limit=20)
            for song in results2:
                if song['title'].lower() == title.lower():
                    archived_song_ids.add(song['song_id'])
                    song_id_to_info[song['song_id']] = (song['title'], artist)
                    found = True
                    break
        if not found:
            print(f"WARNING: Could not find song: {title} by {artist}")
    else:
        print(f"WARNING: No results for: {title} by {artist}")

print(f"\nFound {len(archived_song_ids)} archived song IDs:")
for sid in sorted(archived_song_ids):
    print(f"  {sid}: {song_id_to_info[sid]}")

