steps.code:
# Let's search for each archive song and collect their song IDs
archive_song_ids = []
for song in songs_to_archive:
    query = f"{song['title']} {song['artist']}"
    results = apis.spotify.search_songs(query=query, access_token=login_result["access_token"], page_limit=20)
    # Find exact match
    found = None
    for r in results:
        if r['title'] == song['title'] and any(a['name'] == song['artist'] for a in r['artists']):
            found = r['song_id']
            break
    if found is not None:
        archive_song_ids.append(found)
        print(f"Found: {song['title']} by {song['artist']} -> song_id {found}")
    else:
        print(f"NOT FOUND: {song['title']} by {song['artist']}")

# Verify all archived songs have been removed from existing playlists and are in "Old Songs"
archived_song_ids = {song_id for song_id, _, _ in song_ids_to_archive}

# Re-fetch all playlists to get current state
all_playlists = []
page_index = 0
while True:
    page = apis.spotify.show_playlist_library(access_token=login_result["access_token"], page_index=page_index, page_limit=20)
    all_playlists.extend(page)
    if len(page) < 20:
        break
    page_index += 1

# Check each playlist
for playlist in all_playlists:
    pid = playlist["playlist_id"]
    song_ids = playlist["song_ids"]
    if pid == 654:
        missing = archived_song_ids - set(song_ids)
        if missing:
            print(f"Old Songs playlist missing: {missing}")
        else:
            print(f"Old Songs playlist contains all {len(archived_song_ids)} archived songs.")
    else:
        remaining = set(song_ids) & archived_song_ids
        if remaining:
            print(f"Playlist {pid} ({playlist['title']}) still has archived songs: {remaining}")
        else:
            print(f"Playlist {pid} ({playlist['title']}) clean.")

# Let's inspect the structure of all_playlists to see what we have
print(type(all_playlists))
if isinstance(all_playlists, list):
    print(f"Number of playlists: {len(all_playlists)}")
    if all_playlists:
        print("First playlist keys:", all_playlists[0].keys() if isinstance(all_playlists[0], dict) else all_playlists[0])
else:
    print(all_playlists)

