    for song_id in pl['song_ids']:
        if song_id in old_song_ids:
            # Remove from this playlist
            print(apis.spotify.remove_song_from_playlist(playlist_id=pl_id, song_id=song_id, access_token=spotify_token))
            archived_song_ids.add(song_id)

print("Songs to archive:", sorted(archived_song_ids))

