# Verify all target songs are in playlist 654 and absent from all source playlists
target_ids = {295, 324, 22, 245, 320, 92, 299, 4, 278, 69, 219, 298, 265}

# Fetch all playlists
all_playlists = apis.spotify.show_playlist_library(access_token=spotify_token, page_index=0, page_limit=20)
print("All playlists:", all_playlists)

# Check playlist 654 contents
playlist_654 = apis.spotify.show_playlist(playlist_id=654, access_token=spotify_token)
archived_ids = {song['id'] for song in playlist_654['songs']}
print("Archived playlist song ids:", archived_ids)
print("Missing from archived:", target_ids - archived_ids)

# Check each source playlist for any target song
for pl in all_playlists:
    pl_id = pl['playlist_id']
    if pl_id == 654:
        continue
    pl_data = apis.spotify.show_playlist(playlist_id=pl_id, access_token=spotify_token)
    song_ids = {song['id'] for song in pl_data['songs']}
    overlap = song_ids & target_ids
    if overlap:
        print(f"Playlist {pl_id} still contains target songs: {overlap}")
    else:
        print(f"Playlist {pl_id} clean")

