steps.code:
# Search for each TODO song to get release dates
release_dates = {}
for song in todo_songs:
    query = song['title'] + song['artists'][0]
    # Remove spaces and special chars for better search? The API likely handles it, but let's use the exact title and artist
    result = apis.spotify.search_songs(query=query, page_limit=5)
    # Find the matching song
    found = None
    for s in result:
        if s['title'].lower() == song['title'].lower():
            # Check if any artist matches
            for artist in s.get('artists', []):
                if artist.lower() == song['artists'][0].lower():
                    found = s
                    break
            if found:
                break
    if found:
        release_dates[song['title']] = found['release_date']
        print(f"{song['title']}: {found['release_date']}")
    else:
        print(f"NOT FOUND: {song['title']}")

# The artists field is a list of dicts with 'name' key. Let's search for each song properly.
release_dates = {}
for song in todo_songs:
    query = song['title'] + ' ' + song['artists'][0]
    result = apis.spotify.search_songs(query=query, page_limit=5)
    found = None
    for s in result:
        if s['title'].lower() == song['title'].lower():
            # Check if any artist name matches
            for artist in s.get('artists', []):
                if artist['name'].lower() == song['artists'][0].lower():
                    found = s
                    break
            if found:
                break
    if found:
        release_dates[song['title']] = found['release_date']
        print(f"{song['title']}: {found['release_date']}")
    else:
        print(f"NOT FOUND: {song['title']}")

