# Parse the note content to extract songs with TODO
content = note["content"]
lines = content.split("\n")
songs = []
for line in lines:
    if line.startswith("- "):
        # Remove leading "- "
        line = line[2:]
        # Split by " BY " to get title and artist part
        if " BY " in line:
            title_part, artist_part = line.split(" BY ", 1)
            # artist_part may contain " RELEASED_AT ..."
            if " RELEASED_AT " in artist_part:
                artist_str, released = artist_part.split(" RELEASED_AT ", 1)
            else:
                artist_str = artist_part
                released = ""
            artists = [a.strip() for a in artist_str.split(",")]
            songs.append({"title": title_part.strip(), "artists": artists, "released": released.strip()})
        else:
            # No BY? skip
            pass

